": "", "step_description": "Preview a result, then save it to your library or duplicate it if that option is available."}]}, {"url_pattern": "kahoot.com", "site_name": "Kahoot!", "title": "Assign a homework challenge", "summary": "Assign a kahoot students complete independently.", "description": "Assign a kahoot students complete independently.", "feature_name": "Assignments", "estimated_required_minutes": 2, "keywords": "homework challenge assign self paced due date", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Library", "step_description": "Open your library and choose a kahoot."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Assign", "step_description": "Choose Assign to make a self-paced challenge."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Set the deadline and options, then share the assignment link or PIN with students."}]}, {"url_pattern": "kahoot.com", "site_name": "Kahoot!", "title": "Review game reports", "summary": "Review student scores and class results.", "description": "Review student scores and class results.", "feature_name": "Reports", "estimated_required_minutes": 2, "keywords": "performance reports scores results students analytics", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Reports", "step_description": "Open Reports."}, {"step_order": 2, "step_type": "your_turn", "target_element": "", "step_description": "Select a game report to review class results, player scores, and question-by-question performance."}]}, {"url_pattern": "kahoot.com", "site_name": "Kahoot!", "title": "Add from the question bank", "summary": "Find existing questions to add to a kahoot.", "description": "Find existing questions to add to a kahoot.", "feature_name": "Question bank", "estimated_required_minutes": 2, "keywords": "question bank existing questions add quiz", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "butt