m", "site_name": "Kahoot!", "title": "Play in team mode", "summary": "Let students compete in groups.", "description": "Let students compete in groups.", "feature_name": "Team mode", "estimated_required_minutes": 2, "keywords": "team groups teams competition live game", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Library", "step_description": "Choose a kahoot from your library."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Host live", "step_description": "Start a live game setup."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Choose Team mode in the game experience settings, set team options, and start the game."}]}, {"url_pattern": "kahoot.com", "site_name": "Kahoot!", "title": "Generate quiz questions with AI", "summary": "Generate questions from a topic or learning material.", "description": "Generate questions from a topic or learning material.", "feature_name": "AI quiz generator", "estimated_required_minutes": 2, "keywords": "AI generate quiz questions topic learning material", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Create", "step_description": "Start a new kahoot."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Generate with AI", "step_description": "Choose the AI question generator."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Enter a topic or add learning material, review the generated questions, edit them, and save."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Award behavior points", "summary": "Recognize positive behavior and participation.", "description": "Recognize positive behavior and participation.", "feature_name": "Points", "estimated_required_minutes": 2, "keywords": "behavior points reward positive participation skills", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Class", "step_description": "Open your class view."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Give points", "step_description": "Open the point-awarding controls."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Choose a student and a skill to award a point. Check the selected student before confirming."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Message a parent", "summary": "Send a private message directly to a student's family.", "description": "Send a private message directly to a student's family.", "feature_name": "Messaging", "estimated_required_minutes": 2, "keywords": "parent message family chat private", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Messages", "step_description": "Open Messages or Chats."}, {"step_order": 2, "step_type": "your_turn", "target_element": "", "step_description": "Choose the family conversation, write your message, and send it when ready."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Post a class story", "summary": "Share classroom photos, videos, and updates with families.", "description": "Share classroom photos, videos, and updates with families.", "feature_name": "Class Story", "estimated_required_minutes": 2, "keywords": "class story photos videos updates families post", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Class Story", "step_description": "Open the class story feed."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Create post", "step_description": "Start a new story post."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Add an update or media, check the audience, and publish the post."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Share student portfolio work", "summary": "Share student projects and completed work.", "description": "Share student projects and completed work.", "feature_name": "Portfolios", "estimated_required_minutes": 2, "keywords": "student portfolio projects completed work activity share", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Portfolios", "step_description": "Open the portfolio area for your class."}, {"step_order": 2, "step_type": "your_turn", "target_element": "", "step_description": "Choose a student or portfolio post, review the work, and share or approve it using the available controls."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Record attendance", "summary": "Record student attendance for your class.", "description": "Record student attendance for your class.", "feature_name": "Attendance", "estimated_required_minutes": 2, "keywords": "attendance absent present record students", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Attendance", "step_description": "Open the attendance tool for your class."}, {"step_order": 2, "step_type": "your_turn", "target_element": "", "step_description": "Mark each student present or absent and save the attendance record."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Set a classroom timer", "summary": "Set a timer for an activity or transition.", "description": "Set a timer for an activity or transition.", "feature_name": "Timer", "estimated_required_minutes": 2, "keywords": "classroom timer activity transition countdown", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Tools", "step_description": "Open the classroom tools menu."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Timer", "step_description": "Choose Timer."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Set the time and start the countdown for the activity."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Pick a student at random", "summary": "Randomly select a student to participate.", "description": "Randomly select a student to participate.", "feature_name": "Random picker", "estimated_required_minutes": 2, "keywords": "random student picker choose participate", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Tools", "step_description": "Open the classroom tools menu."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Random", "step_description": "Choose the random student picker."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Use the picker to select a student, then reset or remove the student from the draw if your class needs it."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Make student groups", "summary": "Organize students into groups for an activity.", "description": "Organize students into groups for an activity.", "feature_name": "Groups", "estimated_required_minutes": 2, "keywords": "group maker organize students teams", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Tools", "step_description": "Open the classroom tools menu."}, {"step_order": 2, "step_type": "guided", "target_element": "button:Group Maker", "step_description": "Choose Group Maker."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Choose how many groups or students per group, generate the groups, and adjust them as needed."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Send a class announcement", "summary": "Send important information to families.", "description": "Send important information to families.", "feature_name": "Announcements", "estimated_required_minutes": 2, "keywords": "class announcement families message all parents", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Messages", "step_description": "Open Messages or Chats."}, {"step_order": 2, "step_type": "guided", "target_element": "button:New message", "step_description": "Start a new message."}, {"step_order": 3, "step_type": "your_turn", "target_element": "", "step_description": "Choose the class or family group, write the announcement, and send it."}]}, {"url_pattern": "classdojo.com", "site_name": "ClassDojo", "title": "Review behavior reports", "summary": "Review student behavior and participation patterns.", "description": "Review student behavior and participation patterns.", "feature_name": "Reports", "estimated_required_minutes": 2, "keywords": "behavior reports participation patterns points progress", "steps": [{"step_order": 1, "step_type": "guided", "target_element": "button:Reports", "step_description": "Open Reports for your class."}, {"step_order": 2, "step_type": "your_turn", "target_element": "", "step_description": "Choose a student or date range and review the points and behavior patterns shown in the report."}]}]$seed$::jsonb;
  item jsonb;
  new_tip_id bigint;
BEGIN
  FOR item IN SELECT value FROM jsonb_array_elements(seed)
  LOOP
    INSERT INTO public.websites (url_pattern, name)
    SELECT item->>'url_pattern', item->>'site_name'
    WHERE NOT EXISTS (SELECT 1 FROM public.websites WHERE url_pattern = item->>'url_pattern');

    SELECT tip_id INTO new_tip_id FROM public.tips
      WHERE url_pattern = item->>'url_pattern' AND title = item->>'title' LIMIT 1;
    IF new_tip_id IS NULL THEN
      INSERT INTO public.tips
        (url_pattern, title, summary, description, feature_name, estimated_required_minutes, keywords)
      VALUES
        (item->>'url_pattern', item->>'title', item->>'summary', item->>'description',
         item->>'feature_name', (item->>'estimated_required_minutes')::integer, item->>'keywords')
      RETURNING tip_id INTO new_tip_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.tip_steps WHERE tip_id = new_tip_id) THEN
      INSERT INTO public.tip_steps (tip_id, step_order, step_type, target_element, step_description)
      SELECT new_tip_id, (step->>'step_order')::integer, step->>'step_type',
             step->>'target_element', step->>'step_description'
      FROM jsonb_array_elements(item->'steps') AS steps(step);
    END IF;
    new_tip_id := NULL;
  END LOOP;
END $$;
